    public function getSourceContext(): Source
    {
        return new Source("{% extends 'base.html.twig' %}

{% block title %}Changer le mot de passe - {{ user.fullName }}{% endblock %}

{% block body %}
<div class=\"container mt-4\">
    <div class=\"row justify-content-center\">
        <div class=\"col-md-6\">
            <div class=\"card\">
                <div class=\"card-header\">
                    <h4>Changer le mot de passe pour {{ user.fullName }}</h4>
                </div>
                <div class=\"card-body\">
                    {{ form_start(form) }}
                        {{ form_row(form.plainPassword.first) }}
                        {{ form_row(form.plainPassword.second) }}
                        
                        <div class=\"mt-3\">
                            <button type=\"submit\" class=\"btn btn-primary\">
                                <i class=\"fas fa-save\"></i> Modifier le mot de passe
                            </button>
                            <a href=\"{{ path('app_user_index') }}\" class=\"btn btn-secondary\">
                                <i class=\"fas fa-arrow-left\"></i> Retour
                            </a>
                        </div>
                    {{ form_end(form) }}
                </div>
            </div>
        </div>
    </div>
</div>
{% endblock %}", "admin/change_pasword.html.twig", "C:\\wamp64\\www\\Mes projets en Symfony\\hma_market\\templates\\admin\\change_pasword.html.twig");
